package com.juvinotech.blog.service;
import com.juvinotech.blog.domain.User;import com.juvinotech.blog.dto.ApiDtos.LoginRequest;import com.juvinotech.blog.repository.UserRepository;import com.juvinotech.blog.security.JwtService;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.security.authentication.BadCredentialsException;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.Optional;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class AuthServiceTest {@Mock UserRepository users;@Mock PasswordEncoder encoder;@Mock JwtService jwt;AuthService service;@BeforeEach void setup(){MockitoAnnotations.openMocks(this);service=new AuthService(users,encoder,jwt);}@Test void returnsTokenForValidCredentials(){var u=new User();u.setName("Admin");u.setEmail("admin@test.dev");u.setPasswordHash("hash");when(users.findByEmailIgnoreCase("admin@test.dev")).thenReturn(Optional.of(u));when(encoder.matches("secret","hash")).thenReturn(true);when(jwt.generate(u.getEmail())).thenReturn("token");when(jwt.expirationSeconds()).thenReturn(3600L);assertThat(service.login(new LoginRequest(u.getEmail(),"secret")).token()).isEqualTo("token");}@Test void rejectsInvalidPassword(){var u=new User();u.setPasswordHash("hash");when(users.findByEmailIgnoreCase(any())).thenReturn(Optional.of(u));assertThatThrownBy(()->service.login(new LoginRequest("admin@test.dev","wrong"))).isInstanceOf(BadCredentialsException.class);}}
